package com.ekayn.api.service;
import com.ekayn.api.api.ApiModels.*; import com.ekayn.api.model.User; import com.ekayn.api.repo.UserRepository; import com.ekayn.api.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
@Service @Transactional @RequiredArgsConstructor public class AuthService {
 private final UserRepository users; private final PasswordEncoder encoder; private final JwtService jwt; private final NotificationService notifications; private final AuthRateLimiter limiter;
 private static final Duration TOKEN_TTL=Duration.ofHours(1);
 public Auth register(Register r){limiter.check("register:"+r.email().toLowerCase(Locale.ROOT),5);if(users.findByEmailIgnoreCase(r.email()).isPresent())throw new IllegalArgumentException("Cette adresse est déjà utilisée.");User u=new User();u.setEmail(r.email().toLowerCase(Locale.ROOT));u.setPasswordHash(encoder.encode(r.password()));u.setFirstName(r.firstName());u.setLastName(r.lastName());String token=token();u.setVerificationTokenHash(hash(token));u.setVerificationTokenExpiresAt(Instant.now().plus(TOKEN_TTL));users.save(u);notifications.verification(u,token);return new Auth(jwt.create(u.getId(),u.getEmail(),u.getRole().name(),u.getSessionVersion()),profile(u));}
 public Auth login(Login r){limiter.check("login:"+r.email().toLowerCase(Locale.ROOT),10);User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("Identifiants invalides."));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new IllegalArgumentException("Identifiants invalides.");if(!u.isEmailVerified())throw new IllegalArgumentException("Vérifiez votre adresse email avant de vous connecter.");return new Auth(jwt.create(u.getId(),u.getEmail(),u.getRole().name(),u.getSessionVersion()),profile(u));}
 public void verify(String raw){limiter.check("verify:"+hash(raw),10);User u=users.findByVerificationTokenHash(hash(raw)).orElseThrow(()->new IllegalArgumentException("Token invalide ou expiré."));if(u.getVerificationTokenExpiresAt()==null||u.getVerificationTokenExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Token invalide ou expiré.");u.setEmailVerified(true);u.setVerificationTokenHash(null);u.setVerificationTokenExpiresAt(null);users.save(u);}
 public void resend(String email){limiter.check("resend:"+email.toLowerCase(Locale.ROOT),3);users.findByEmailIgnoreCase(email).filter(u->!u.isEmailVerified()).ifPresent(u->{String token=token();u.setVerificationTokenHash(hash(token));u.setVerificationTokenExpiresAt(Instant.now().plus(TOKEN_TTL));users.save(u);notifications.verification(u,token);});}
 public void forgot(String email){limiter.check("forgot:"+email.toLowerCase(Locale.ROOT),3);users.findByEmailIgnoreCase(email).ifPresent(u->{String token=token();u.setResetTokenHash(hash(token));u.setResetTokenExpiresAt(Instant.now().plus(TOKEN_TTL));users.save(u);notifications.passwordReset(u,token);});}
 public void reset(PasswordReset r){limiter.check("reset:"+r.email().toLowerCase(Locale.ROOT),5);User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new IllegalArgumentException("Token invalide ou expiré."));if(r.token()==null||!hash(r.token()).equals(u.getResetTokenHash())||u.getResetTokenExpiresAt()==null||u.getResetTokenExpiresAt().isBefore(Instant.now()))throw new IllegalArgumentException("Token invalide ou expiré.");u.setPasswordHash(encoder.encode(r.newPassword()));u.setResetTokenHash(null);u.setResetTokenExpiresAt(null);u.setSessionVersion(u.getSessionVersion()+1);users.save(u);}
 private ProfileResponse profile(User u){return new ProfileResponse(u.getId(),u.getEmail(),u.getFirstName(),u.getLastName(),u.getPhone(),u.isEmailVerified(),u.getRole().name());}
 private String token(){byte[] bytes=new byte[32];new SecureRandom().nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
 public static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(GeneralSecurityException e){throw new IllegalStateException(e);}}
}
